onChange.script:
if origin == 'BindingWriteback':

	startDate = self.params.values.startDate
	cutoffDate = system.date.setTime(self.custom.ends.cutoffDate, 23, 59, 59)
	vals = self.custom.values
	ends = self.custom.ends.selection
	count = self.custom.ends.count or 1
	untilDate = None
	if cutoffDate is None: pass
	elif ends == 'on': untilDate = system.kanoa.utilities.javaDateToPython(cutoffDate).strftime('%Y%m%dT%H%M%S')
	elif ends == 'after':
		if vals['FREQ'] == 'DAILY': untilDate = system.date.addDays(startDate, count)
		elif vals['FREQ'] == 'WEEKLY': untilDate = system.date.addWeeks(startDate, count)
		elif vals['FREQ'] == 'MONTHLY': untilDate = system.date.addMonths(startDate, count)
		elif vals['FREQ'] == 'YEARLY': untilDate = system.date.addYears(startDate, count)

		untilDate = system.date.midnight(untilDate)
		untilDate = system.kanoa.utilities.javaDateToPython(untilDate).strftime('%Y%m%dT%H%M%S')

	vals['UNTIL'] = untilDate

return

transforms.code:

rruleParams = {"FREQ": 'WEEKLY', "INTERVAL": 1, "BYWEEKDAY": None, "BYMONTHDAY": None, "UNTIL": None, 'monthly': None}
weekDays = {'MO': False, 'TU': False, 'WE': False, 'TH': False, 'FR': False, 'SA': False, 'SU': False}	
weekdayMap = {'1': 'SU', '2': 'MO', '3': 'TU', '4': 'WE', '5': 'TH', '6': 'FR', '7': 'SA'}
weekdayList = ['MO', 'TU', 'WE', 'TH', 'FR', 'SA', 'SU']

rruleStr = self.view.params.values.rruleStr
if rruleStr or None is not None:
	rruleSections = rruleStr.split(";")
	for rruleSection in rruleSections:
		k, v = rruleSection.split("=")
		rruleParams[k] = v

if rruleParams['FREQ'] == 'MONTHLY':
	if rruleParams["BYMONTHDAY"]:
		rruleParams['monthly'] = system.util.jsonEncode({"dayOfMonth": int(rruleParams["BYMONTHDAY"]), "choice": "nth day of month"})
	elif rruleParams["BYWEEKDAY"]:
		byWeekDaySplit = rruleParams["BYWEEKDAY"].split("(")
		weekOfMonth = int(byWeekDaySplit[1][:-1])
		dayOfWeek = int(weekdayMap.keys()[weekdayMap.values().index(byWeekDaySplit[0])])
		rruleParams['monthly'] = system.util.jsonEncode({"weekOfMonth": weekOfMonth, "dayOfWeek": dayOfWeek, "choice": "nth weekday of month"})
elif rruleParams['FREQ'] == 'WEEKLY':
	if rruleParams['BYWEEKDAY'] is None:
		rruleParams['BYWEEKDAY'] = ",".join([k for k,v in self.custom.weekdays.items() if v])

if rruleParams.has_key("UNTIL") and rruleParams["UNTIL"] is not None:
	self.custom.ends.selection = 'on'
	assetInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.asset.getAssets({'assetPath': value['assetPath']}), 0)
	cutoffDate = system.date.parse(rruleParams['UNTIL'], "yyyyMMdd'T'HHmmss")
	tzOffsetMins = system.kanoa.date.getTimeZoneOffsetMins(assetInfo['timeZone'], cutoffDate)
	self.custom.ends.cutoffDate = system.date.addMinutes(cutoffDate, -tzOffsetMins)
else:
	self.custom.ends.selection = 'never'

#Now initialize the weekday selector
startDate = self.view.params.values.startDate
dayOfWeek = str(system.date.getDayOfWeek(startDate))
byWeekDay = rruleParams['BYWEEKDAY']

for weekday in weekdayList:
	if weekdayMap[dayOfWeek] == weekday: weekDays[weekday] = True
	elif rruleParams['FREQ'] == 'WEEKLY' and (rruleParams["BYWEEKDAY"] is None or weekday in rruleParams["BYWEEKDAY"]): weekDays[weekday] = True

self.custom.weekdays = weekDays

return rruleParams

